<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class LibraryPrintController extends Controller{
 private function manage(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('librarian')||$r->user()->canDo('library.manage'),403);}
 public function reader(Request $r,$id){$this->manage($r);$x=DB::table('library_readers as lr')->leftJoin('students as s','s.id','=','lr.student_id')->leftJoin('teachers as t','t.id','=','lr.teacher_id')->leftJoin('study_groups as g','g.id','=','s.current_group_id')->where('lr.id',$id)->select('lr.*','s.last_name student_last','s.first_name student_first','s.middle_name student_middle','t.last_name teacher_last','t.first_name teacher_first','t.middle_name teacher_middle','g.name group_name')->first();abort_if(!$x,404);return view('library.print-reader',compact('x'));}
 public function labels(Request $r,$book){$this->manage($r);$b=DB::table('library_books')->find($book);abort_if(!$b,404);$copies=DB::table('library_copies')->where('library_book_id',$book)->whereNotIn('status',['written_off','lost'])->get();return view('library.print-labels',compact('b','copies'));}
 public function inventory(Request $r,$id){$this->manage($r);$inv=DB::table('library_inventories')->find($id);abort_if(!$inv,404);$rows=DB::table('library_copies as c')->join('library_books as b','b.id','=','c.library_book_id')->leftJoin('library_inventory_scans as s',fn($j)=>$j->on('s.library_copy_id','=','c.id')->where('s.library_inventory_id',$id))->whereNotIn('c.status',['written_off','lost'])->select('c.inventory_number','c.barcode','c.location','b.title','s.scanned_at')->orderBy('b.title')->get();return view('library.print-inventory',compact('inv','rows'));}
 public function writeoffs(Request $r){$this->manage($r);$rows=DB::table('library_copies as c')->join('library_books as b','b.id','=','c.library_book_id')->where('c.status','written_off')->select('c.*','b.title','b.authors')->orderByDesc('c.written_off_on')->get();return view('library.print-writeoffs',compact('rows'));}
 public function scan(Request $r){$this->manage($r);return view('library.scan');}
 public function resolve(Request $r){$this->manage($r);$d=$r->validate(['code'=>'required|string|max:100']);$reader=DB::table('library_readers')->where(fn($q)=>$q->where('barcode',$d['code'])->orWhere('card_number',$d['code']))->where('active',1)->first();if($reader)return response()->json(['type'=>'reader','id'=>$reader->id,'student_id'=>$reader->student_id,'teacher_id'=>$reader->teacher_id,'label'=>$reader->card_number]);$copy=DB::table('library_copies as c')->join('library_books as b','b.id','=','c.library_book_id')->where(fn($q)=>$q->where('c.barcode',$d['code'])->orWhere('c.inventory_number',$d['code']))->select('c.*','b.title')->first();if($copy)return response()->json(['type'=>'copy','id'=>$copy->id,'status'=>$copy->status,'label'=>$copy->title.' · '.$copy->inventory_number]);return response()->json(['error'=>'Код не найден'],404);}
 public function quickIssue(Request $r){$this->manage($r);$d=$r->validate(['reader_id'=>'required|exists:library_readers,id','copy_id'=>'required|exists:library_copies,id','due_on'=>'required|date|after_or_equal:today']);$reader=DB::table('library_readers')->find($d['reader_id']);$copy=DB::table('library_copies')->find($d['copy_id']);abort_unless($reader->active&&$copy->status==='available',422);DB::transaction(function()use($reader,$copy,$d,$r){DB::table('library_loans')->insert(['library_copy_id'=>$copy->id,'student_id'=>$reader->student_id,'teacher_id'=>$reader->teacher_id,'issued_by'=>$r->user()->id,'issued_at'=>now(),'due_on'=>$d['due_on'],'created_at'=>now(),'updated_at'=>now()]);DB::table('library_copies')->where('id',$copy->id)->update(['status'=>'loaned','updated_at'=>now()]);DB::table('library_reservations')->where('library_book_id',$copy->library_book_id)->where($reader->student_id?'student_id':'teacher_id',$reader->student_id?:$reader->teacher_id)->where('status','waiting')->update(['status'=>'fulfilled','updated_at'=>now()]);});return response()->json(['ok'=>true]);}
}